#!/usr/bin/env node
/**
 * generate-ssg-routes.js — writes src/ssgRoutes.generated.js, a flat array
 * of every pathname ssg-build.js will prerender.
 *
 * Runs BEFORE `vite build` (and before `vite` dev-serves anything — wired
 * as `predev` too) so main.jsx can statically import the manifest (a few
 * KB of path strings) instead of the large blog/city/comparison/faq
 * content files just to decide hydrateRoot vs createRoot. See
 * src/ssgRoutes.js for why keeping those content files out of the eager
 * entry bundle matters.
 *
 * The generated file is git-ignored — always regenerated, never hand-
 * edited, never committed stale.
 *
 * Usage: node scripts/generate-ssg-routes.js
 */

import { writeFileSync } from 'fs'
import { resolve, dirname } from 'path'
import { fileURLToPath } from 'url'
import { buildBaseSsgPaths } from '../src/ssgRoutes.js'
import { BLOG_POSTS } from '../src/data/blogPosts.js'
import { CITY_PAGES } from '../src/data/cityPages.js'
import { COMPARISON_PAGES } from '../src/data/comparisonPages.js'
import { FAQ_PAGES } from '../src/data/faqPages.js'

const __dirname = dirname(fileURLToPath(import.meta.url))
const OUT_PATH = resolve(__dirname, '../src/ssgRoutes.generated.js')

const paths = buildBaseSsgPaths()
for (const post of BLOG_POSTS) paths.add(`/blog/${post.slug}`)
for (const page of CITY_PAGES) paths.add(`/${page.slug}`)
for (const page of COMPARISON_PAGES) paths.add(`/compare/${page.slug}`)
for (const page of FAQ_PAGES) paths.add(`/faq/${page.slug}`)

const sorted = [...paths].sort()

const banner = '// AUTO-GENERATED by scripts/generate-ssg-routes.js — do not edit by hand.\n'
const body = `export const SSG_PATHS = ${JSON.stringify(sorted, null, 2)}\n`
writeFileSync(OUT_PATH, banner + body, 'utf-8')

console.log(`Wrote ${sorted.length} SSG paths to src/ssgRoutes.generated.js`)
